"""The wizard against ArduPilot's own Rover parameter metadata (tests/util/apm_pdef.json, generated by ArduPilot from
its source code): every parameter field shows ArduPilot's description, and every value the wizard offers or writes is
one ArduPilot defines."""

import json
import re
import math
from pathlib import Path

import pytest

import rover_wizard.rover_defs as rover_defs
from rover_wizard.ui.param_docs import DOCS_FILE, is_documented
from rover_wizard.ui.step_catalog import STEPS
from rover_wizard.steps.util.outputs import SPRAYER_SERVO_FUNCTIONS

from util.extract_param_docs import SOURCE as METADATA_FILE
from util.extract_param_docs import extract
from util.helpers import make

# Parameters of older firmware that today's metadata no longer documents; their fields keep the wizard's own help.
OLDER_FIRMWARE_ONLY = {
    "ARMING_CHECK",
    "RNGFND1_MIN_CM",
    "RNGFND1_MAX_CM",
    "WP_OVERSHOOT",
    "NAVL1_PERIOD",
    "NAVL1_DAMPING",
}


@pytest.fixture(scope="module")
def metadata():
    """name -> ArduPilot's metadata entry, for every Rover parameter."""
    groups = json.loads(METADATA_FILE.read_text(encoding="utf-8"))
    return {name: info for group in groups.values() for name, info in group.items()}


def parameter_fields(skid: bool):
    """(step id, field, resolved parameter name) for every parameter field, as the simulated vehicle resolves them."""
    vehicle, ctx = make(skid=skid)
    rows = []
    for step in STEPS:
        for field in step.fields:
            if field.param is None:
                continue
            names = field.names(ctx)
            names = (names,) if isinstance(names, str) else tuple(names)
            rows.append((step.id, field, vehicle.resolve(names) or names[0]))
    vehicle.disconnect()
    return rows


@pytest.mark.parametrize("skid", [False, True], ids=["ackermann", "skid"])
def test_every_parameter_field_has_arduPilots_description(skid):
    undocumented = sorted(
        {
            f"{step}.{field.key} ({name})"
            for step, field, name in parameter_fields(skid)
            if not is_documented(name) and name not in OLDER_FIRMWARE_ONLY
            # SERVO0_: role not on this vehicle type (hidden)
            and not name.startswith("SERVO0_")
        }
    )
    assert not undocumented


def test_older_firmware_list_is_still_accurate(metadata):
    still_documented = sorted(name for name in OLDER_FIRMWARE_ONLY if name in metadata)
    assert not still_documented, "these now have descriptions - remove them from OLDER_FIRMWARE_ONLY"


def test_param_docs_json_is_up_to_date():
    assert (
        json.loads(Path(DOCS_FILE).read_text(encoding="utf-8")) == extract()
    ), "run: python tests/util/extract_param_docs.py"


@pytest.mark.parametrize("skid", [False, True], ids=["ackermann", "skid"])
def test_choices_and_bits_are_arduPilots_values(metadata, skid):
    problems = []
    for step, field, name in parameter_fields(skid):
        info = metadata.get(name, {})
        if field.choices and info.get("Values"):
            official = {float(value) for value in info["Values"]}
            problems += [
                f"{step}.{field.key}: {value} '{label}' not a value of {name}"
                for label, value in field.choices
                if float(value) not in official
            ]
        # bit value -> bit index
        if field.bit is not None and info.get("Bitmask") and str(int(math.log2(field.bit))) not in info["Bitmask"]:
            problems.append(f"{step}.{field.key}: bit {field.bit} not in {name}'s bitmask")
    assert not problems


def test_numbers_the_code_writes_are_arduPilots_values(metadata):
    functions = metadata["SERVO1_FUNCTION"]["Values"]
    options = metadata["RC1_OPTION"]["Values"]
    protocols = metadata["SERIAL1_PROTOCOL"]["Values"]
    servo_functions = [
        rover_defs.SERVO_FUNCTION_GPIO,
        rover_defs.SERVO_FUNCTION_RC_PASSTHRU,
        rover_defs.SERVO_FUNCTION_GROUND_STEERING,
        rover_defs.SERVO_FUNCTION_THROTTLE,
        rover_defs.SERVO_FUNCTION_THROTTLE_LEFT,
        rover_defs.SERVO_FUNCTION_THROTTLE_RIGHT,
        rover_defs.SERVO_FUNCTION_GRIPPER,
        *SPRAYER_SERVO_FUNCTIONS.values(),
        *(rover_defs.SERVO_FUNCTION_RCIN_BASE + channel for channel in range(1, 17)),
    ]
    rc_options = [
        *rover_defs.RC_OPTION_RELAY.values(),
        rover_defs.RC_OPTION_GRIPPER,
        rover_defs.RC_OPTION_EKF_SOURCE_SET,
    ]
    serial_protocols = [getattr(rover_defs, name) for name in dir(rover_defs) if name.startswith("SERIAL_PROTOCOL_")]
    assert [f for f in servo_functions if str(f) not in functions] == []
    assert [o for o in rc_options if str(o) not in options] == []
    assert [p for p in serial_protocols if str(p) not in protocols] == []


def test_meanings_and_live_reading_of_named_values_and_bitmasks():
    from rover_wizard.ui.param_docs import meanings, reading

    assert meanings("COMPASS_AUTODEC") == ["0 = Disabled", "1 = Enabled"]
    assert (reading("COMPASS_AUTODEC", 1), reading("COMPASS_AUTODEC", 7)) == ("Enabled", "not one of the listed values")
    # bitmask: each line is the bit's value
    assert meanings("AVOID_ENABLE") == ["1 = UseFence", "2 = UseProximitySensor", "4 = UseBeaconFence"]
    assert reading("AVOID_ENABLE", 3) == "UseFence, UseProximitySensor"
    assert reading("AVOID_ENABLE", 0) == "nothing selected"
    # a set bit without a name, and -1 as ArduPilot's 32-bit "all bits"
    assert reading("AVOID_ENABLE", 8) == "bit 3"
    assert reading("AVOID_ENABLE", -1).startswith("UseFence, UseProximitySensor, UseBeaconFence, bit 3")
    assert reading("AVOID_ENABLE", 1.5) == "a bitmask needs a whole number"
    # a plain number reads as nothing
    assert reading("WP_SPEED", 2) == ""


def test_parameter_validation():
    from rover_wizard.ui.param_docs import validation_error

    assert validation_error("COMPASS_CAL_FIT", 16) == ""
    assert "outside ArduPilot's range 4 .. 32" in validation_error("COMPASS_CAL_FIT", 50)
    assert validation_error("COMPASS_AUTODEC", 0.5) == "needs a whole number"
    assert validation_error("WP_SPEED", None) == "not a number"
    assert validation_error("COMPASS_DEV_ID", 1).startswith("read-only")


# How ArduPilot's metadata marks values only for old firmware, or retired ones (e.g. RCx_OPTION 41
# "ArmDisarm (4.1 and lower)": current firmware answers "Invalid channel option (41)").
OLD_OR_RETIRED = re.compile(r"\b\d+\.\d+ and (lower|older)\b|deprecated", re.IGNORECASE)


@pytest.mark.parametrize("skid", [False, True], ids=["ackermann", "skid"])
def test_no_choice_is_only_for_old_firmware(metadata, skid):
    offered = set()
    for step, field, name in parameter_fields(skid):
        values = metadata.get(name, {}).get("Values", {})
        for label, value in field.choices or []:
            official = values.get(str(int(value)) if float(value).is_integer() else str(value), "")
            if OLD_OR_RETIRED.search(official):
                offered.add(f"{step}.{field.key}: {value} '{label}' - ArduPilot: '{official}'")
    assert not offered, sorted(offered)
